def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform, nonzero rows/columns are the panel dividers.
    row_divs = [r for r in range(h)
                if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    col_divs = [c for c in range(w)
                if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def intervals(size, divs):
        parts = []
        start = 0
        for d in divs:
            if start < d:
                parts.append((start, d))
            start = d + 1
        if start < size:
            parts.append((start, size))
        return parts

    rows = intervals(h, row_divs)
    cols = intervals(w, col_divs)
    out = [row[:] for row in grid]

    def reflect(mask, height, width, flip_v, flip_h):
        return {
            (height - 1 - r if flip_v else r,
             width - 1 - c if flip_h else c)
            for r, c in mask
        }

    # Look for 2x2 panel groups with three matching reflected copies.
    for ri in range(len(rows) - 1):
        r0, r1 = rows[ri]
        r2, r3 = rows[ri + 1]
        if r1 - r0 != r3 - r2:
            continue
        ph = r1 - r0

        for ci in range(len(cols) - 1):
            c0, c1 = cols[ci]
            c2, c3 = cols[ci + 1]
            if c1 - c0 != c3 - c2:
                continue
            pw = c1 - c0

            for color in range(1, 10):
                masks = {}
                for pi in range(2):
                    for pj in range(2):
                        rr0, rr1 = rows[ri + pi]
                        cc0, cc1 = cols[ci + pj]
                        masks[pi, pj] = {
                            (r - rr0, c - cc0)
                            for r in range(rr0, rr1)
                            for c in range(cc0, cc1)
                            if grid[r][c] == color
                        }

                present = [pos for pos, mask in masks.items() if mask]
                if len(present) != 3:
                    continue

                # Convert each present panel's pattern back to the top-left orientation.
                canonical = None
                valid = True
                for pi, pj in present:
                    norm = reflect(masks[pi, pj], ph, pw, bool(pi), bool(pj))
                    if canonical is None:
                        canonical = norm
                    elif norm != canonical:
                        valid = False
                        break
                if not valid:
                    continue

                missing = next((pi, pj) for pi in range(2) for pj in range(2)
                               if (pi, pj) not in present)
                pi, pj = missing
                target = reflect(canonical, ph, pw, bool(pi), bool(pj))
                rr0, _ = rows[ri + pi]
                cc0, _ = cols[ci + pj]
                for r, c in target:
                    out[rr0 + r][cc0 + c] = color

    return out
